import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import crypto from 'node:crypto';
import {ORIGINS} from '../origin-content.js';import {dialoguePages} from '../dialogue-presentation.js';
const root=new URL('../voices/',import.meta.url),manifest=JSON.parse(fs.readFileSync(new URL('manifest.json',root))),script=JSON.parse(fs.readFileSync(new URL('../../story/voice-script.json',import.meta.url)));
test('every packaged voice is an exact current campaign or origin turn with an intact local audio asset',()=>{const keys=new Set(script.lines.map(l=>l.speaker+'\0'+l.text)),seen=new Set();for(const origin of ORIGINS)for(const value of Object.values(origin)){const pages=typeof value==='string'?[value]:Array.isArray(value)?value.filter(v=>typeof v==='string'):[];for(const page of dialoguePages(pages))for(const line of page.voiceSegments)keys.add(line.speaker+'\0'+line.text);}for(const l of manifest.lines){const key=l.speaker+'\0'+l.text;assert.ok(keys.has(key),l.id);assert.ok(!seen.has(key),l.id);seen.add(key);assert.ok(!l.audio.includes('://'));const bytes=fs.readFileSync(new URL(l.audio,root));assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),l.sha256);assert.ok(l.duration_seconds>.1);}assert.equal(script.unique_spoken_turns,script.lines.length);assert.equal(script.recorded_turns,script.lines.filter(l=>seen.has(l.speaker+'\0'+l.text)).length);});
test('recorded turns cover every campaign chapter and exclude interface receipts',()=>{const recorded=new Set(manifest.lines.map(l=>l.speaker+'\0'+l.text)),chapters=new Set();for(const l of script.lines)if(recorded.has(l.speaker+'\0'+l.text))for(const r of l.source_records)if(r.chapter)chapters.add(r.chapter);for(let c=1;c<=24;c++)assert.ok(chapters.has(c),'chapter '+c);for(const l of manifest.lines)assert.ok(!/^(Received|Found|Learned|Rewards|Controls):/.test(l.text));});
